// AI-generated By Mark and chat gpt

bool loadImage(Image &image) {
    string imageName;
    cout << "Enter image file name to load: ";
    cin >> imageName;
    if (!image.load(imageName)) {
        cout << "Failed to load image: " << imageName << endl;
        return false;
    }
    cout << "Image loaded successfully!" << endl;
    return true;
}

bool saveImage(const Image &image) {
    string imageName;
    cout << "Enter image file name to save: ";
    cin >> imageName;
    if (!image.save(imageName)) {
        cout << "Failed to save image: " << imageName << endl;
        return false;
    }
    cout << "Image saved successfully!" << endl;
    return true;
}
