// filter 10 Mark
void detectImageEdges(Image &image) {
    int _w = image.width;
    int _h = image.height;
    int _c = image.channels;

    unsigned char *grayImage = new unsigned char[_w * _h];
    for (int _y = 0; _y < _h; _y++) {
        for (int _x = 0; _x < _w; _x++) {
            int idx = (_y * _w + _x) * _c;
            int r = image.data[idx];
            int g = image.data[idx + 1];
            int b = image.data[idx + 2];
            grayImage[_y * _w + _x] = (unsigned char)((r + g + b) / 3);
        }
    }

    unsigned char *edgesImage = new unsigned char[_w * _h];
    for (int _y = 0; _y < _h; _y++) {
        for (int _x = 0; _x < _w; _x++) {
            int _xNext = (_x + 1 < _w) ? _x + 1 : _x;
            int _yNext = (_y + 1 < _h) ? _y + 1 : _y;

            int gx = grayImage[_y * _w + _xNext] - grayImage[_y * _w + _x];
            int gy = grayImage[_yNext * _w + _x] - grayImage[_y * _w + _x];

            int magnitude = (int)sqrt((double)(gx * gx + gy * gy));

            if (magnitude > 50) {
                edgesImage[_y * _w + _x] = 255;
            } else {
                edgesImage[_y * _w + _x] = 0;
            }
        }
    }

    for (int _y = 0; _y < _h; _y++) {
        for (int _x = 0; _x < _w; _x++) {
            int idx = (_y * _w + _x) * _c;
            unsigned char edgeVal = edgesImage[_y * _w + _x];
            image.data[idx]     = edgeVal;
            image.data[idx + 1] = edgeVal;
            image.data[idx + 2] = edgeVal;
        }
    }

    delete[] grayImage;
    delete[] edgesImage;
}
