// filter 14 mark
void wanoTVNoiseImage(Image &image) {
    int _w = image.width;
    int _h = image.height;
    int _c = image.channels;

    srand((unsigned)time(0));

    for (int _y = 0; _y < _h; _y++) {
        for (int _x = 0; _x < _w; _x++) {
            int idx = (_y * _w + _x) * _c;

            int noise = rand() % 256;

            if ((_y % 2) == 0) {
                noise = (int)(noise * 0.7);
            }

            int rollBar = (int)(sin(_x * 0.05) * 30);

            int originalAvg = (image.data[idx] + image.data[idx + 1] + image.data[idx + 2]) / 3;

            int mixed = (originalAvg * 30 + noise * 70) / 100 + rollBar;

            int r = mixed + (rand() % 20 - 10);
            int g = mixed + (rand() % 20 - 10);
            int b = mixed + (rand() % 20 - 10);

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            image.data[idx]     = (unsigned char)r;
            image.data[idx + 1] = (unsigned char)g;
            image.data[idx + 2] = (unsigned char)b;
        }
    }
}
