void showMenu() {
    cout << "\n========= Baby Photoshop Menu =========" << endl;
    cout << "10. Filter 10: Detect Image Edges" << endl;
    cout << "14. Filter 14: Wano TV Noise Image" << endl;
    cout << "0. Exit" << endl;
    cout << "=====================================" << endl;
    cout << "Enter your choice: ";
}
//***/ /***//*** //***//***//*** //

int main() {
    Image image;
    int choice;

    if (!loadImage(image)) return 1;

    do {
        showMenu();
        cin >> choice;

        if (choice == 10) {
            detectImageEdges(image);
            cout << "Edge detection applied to image." << endl;
        } else if (choice == 14) {
            wanoTVNoiseImage(image);
            cout << "TV noise effect applied to image." << endl;
        } else if (choice == 0) {
            cout << "Exiting..." << endl;
        } else {
            cout << "Invalid choice. Try again." << endl;
        }

        if (choice == 10 || choice == 14) {
            saveImage(image);
            cout << "\nDo you want to load a new image? (1 = yes, 0 = no): ";
            int reload;
            cin >> reload;
            if (reload == 1) {
                if (!loadImage(image)) return 1;
            }
        }
    } while (choice != 0);

    return 0;
}